insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-04','verbeterd','Platform','Het menu klapt niet meer per ongeluk open',
   'Het smalle menu aan de linkerkant klapte open zodra je muis de balk raakte, ook als je gewoon langs de rand aan het werk was. Nu gebeurt dat alleen nog als je echt op een icoontje staat. Zodra het menu openstaat, blijft het open tot je de muis er helemaal vanaf haalt.');
